H.background();
const Z = Math.max(1, Math.min(10, Math.round(P.Z)));
// AP PES: x-axis = binding energy (increasing to the LEFT), peak height = # electrons.
const order = [
  {name:"1s", cap:2, base:100},
  {name:"2s", cap:2, base:12},
  {name:"2p", cap:6, base:8}
];
let remaining = Z;
const peaks = [];
for (const sh of order){
  if (remaining <= 0) break;
  const e = Math.min(sh.cap, remaining);
  remaining -= e;
  const be = sh.base * Math.pow(Z/ (sh.name==="1s"?2: (sh.name==="2s"?4:5)), 0.9) + sh.base*0.2;
  peaks.push({name: sh.name, n: e, be: be});
}
let maxBE = 1;
for (const p of peaks) maxBE = Math.max(maxBE, p.be);
const v = H.plot2d({ xMin: 0, xMax: maxBE*1.15, yMin: 0, yMax: 7 });
